    <script>
        const timezone = @json(config('app.timezone'));
        const clock = document.getElementById('reservation-clock');
        const refreshClock = () => { clock.textContent = new Intl.DateTimeFormat('en-US', { timeZone: timezone, month: 'short', day: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date()).replace(',', ' •'); };
        refreshClock(); setInterval(refreshClock, 30000);
        const guest = document.getElementById('guest_id'); const room = document.getElementById('room_id'); const checkIn = document.getElementById('check_in_date'); const checkOut = document.getElementById('check_out_date'); const guestCount = document.getElementById('number_of_guests'); const capacityNote = document.getElementById('capacity-note'); const existingGuestFields = document.getElementById('existing-guest-fields'); const manualGuestFields = document.getElementById('manual-guest-fields'); const manualFirstName = document.getElementById('manual_guest_first_name'); const manualLastName = document.getElementById('manual_guest_last_name');
        const money = value => `PHP ${Number(value || 0).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
        const updateSummary = () => { const selectedRoom = room.options[room.selectedIndex]; const rate = Number(selectedRoom?.dataset.rate || 0); const capacity = selectedRoom?.dataset.capacity; const start = checkIn.value ? new Date(`${checkIn.value}T00:00:00`) : null; const end = checkOut.value ? new Date(`${checkOut.value}T00:00:00`) : null; const nights = start && end && end > start ? Math.round((end - start) / 86400000) : 0; const manualName = `${manualFirstName?.value || ''} ${manualLastName?.value || ''}`.trim(); document.getElementById('summary-guest').textContent = guest.value ? guest.options[guest.selectedIndex].text.split(' - ')[0] : (manualName || 'Not selected'); document.getElementById('summary-room').textContent = room.value ? selectedRoom.text.split(' - ')[0] : 'Not selected'; document.getElementById('summary-dates').textContent = nights ? `${nights} night${nights === 1 ? '' : 's'}` : 'Not selected'; document.getElementById('summary-guests').textContent = guestCount.value || '1'; document.getElementById('summary-total').textContent = money(rate * nights); document.getElementById('summary-deposit').textContent = money(rate * nights * .5); capacityNote.textContent = capacity ? `Capacity: ${capacity} guest${capacity === '1' ? '' : 's'}` : ''; if (capacity) guestCount.max = capacity; };
        const updateGuestMode = mode => { const manual = mode === 'manual'; existingGuestFields.classList.toggle('hidden', manual); manualGuestFields.classList.toggle('hidden', !manual); guest.disabled = manual; manualFirstName.required = manual; manualLastName.required = manual; if (manual) guest.value = ''; updateSummary(); };
        document.querySelectorAll('input[name="guest_mode"]').forEach(input => input.addEventListener('change', event => updateGuestMode(event.target.value)));
        [guest, room, checkIn, checkOut, guestCount, manualFirstName, manualLastName].forEach(field => field?.addEventListener('input', updateSummary));
        updateGuestMode(document.querySelector('input[name="guest_mode"]:checked')?.value || 'existing');
        updateSummary();
    </script>
